@ConfigurationProperties("p103")
public record P103Properties(String control, String reporte, int sentinelaFin) {}

/** WKS-REG-HD-CONTROL: primer registro del archivo. */
public record HeaderControl(int csi,                 // 9(02)
                            LocalDate fechaProceso)  // 9(08) AAAAMMDD
{}

/** WKS-REG-DET-CONTROL: un registro por sistema alimentador; 999 termina la lista. */
public record DetalleControl(int sistema,            // 9(03)
                             LocalDate fechaProceso) // 9(08)
{
    boolean esSentinela(int fin) { return sistema == fin; }
}

public record ControlCorporativo(HeaderControl header, List<DetalleControl> sistemas) {}

static LocalDate aaaammdd(String s) {
    return LocalDate.parse(s, DateTimeFormatter.BASIC_ISO_DATE);
}

@Configuration
public class ControlFechasJobConfig {

    /** El WFL pasaba 01 o 02; aquí es un JobParameter validado. */
    @Bean
    Job controlFechas(JobRepository repo, Step consultaFecha, Step proyectaFecha) {
        JobExecutionDecider modo = (je, se) -> new FlowExecutionStatus(
                switch (je.getJobParameters().getString("parametro")) {
                    case "01" -> "CONSULTA";
                    case "02" -> "PROYECTA";
                    default   -> throw new IllegalArgumentException(
                            "W77-PARAMETRO debe ser 01 o 02");   // en COBOL: STOP RUN sin hacer nada
                });
        return new JobBuilder("S151P103", repo)
                .start(modo)
                    .on("CONSULTA").to(consultaFecha)
                .from(modo)
                    .on("PROYECTA").to(proyectaFecha)
                .end()
                .build();
    }
}

@Component
@RequiredArgsConstructor
public class ConsultaFechaTasklet implements Tasklet {

    private final ControlCorporativoRepository control;
    private final Bitacora bitacora;                  // 000-030-IMPRIME-MENSAJE / LIB-DISP

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        HeaderControl h = control.leeHeader();        // OPEN INPUT + READ
        bitacora.info("INICIO PROCESO PARA CONSULTA DE FECHA DE PROCESO : " + h.fechaProceso());

        // CHANGE ATTRIBUTE VALUE OF MYSELF TO WKS-FEC-6D: el WFL lee la fecha como AAMMDD.
        // En Java se publica completa y el adaptador del orquestador decide el formato.
        ctx.getStepContext().getStepExecution().getJobExecution()
           .getExecutionContext().put("fechaProceso", h.fechaProceso());
        c.setExitStatus(new ExitStatus("COMPLETED",
                h.fechaProceso().format(DateTimeFormatter.ofPattern("yyMMdd"))));
        return RepeatStatus.FINISHED;
    }
}

public interface CalendarioBancario {
    /** THECALENDAR función 13, formato 12, WKS-FECHA2 = 00000001. */
    LocalDate siguienteHabil(LocalDate desde, int dias);
}

// ProyectaFechaTasklet
LocalDate proxima;
try {
    proxima = calendario.siguienteHabil(h.fechaProceso(), 1);
} catch (CalendarioException e) {                     // W77-FUNCION > 0
    bitacora.error("ERROR AL PROYECTAR PROXIMA FECHA DE PROCESO, NECESARIA PARA ACTUALIZAR ARCHIVO "
            + props.control());
    throw new ProcesoAbortadoException(e);              // SET MYSELF(STATUS) TO -1
}

/** 000100-CHECA-STATUS UNTIL W77-FIN = 1. */
List<RenglonEstatus> estatus(ControlCorporativo cc) {
    var renglones = new ArrayList<RenglonEstatus>();
    for (DetalleControl d : cc.sistemas()) {                     // AT END también termina
        if (d.esSentinela(props.sentinelaFin())) break;         // WKS-DET-SIST = 999
        String msg = d.fechaProceso().equals(cc.header().fechaProceso())
                ? "SE EJECUTO CORRECTAMENTE"
                : "NO HA SIDO PROCESADO DESDE";                 // seguido de la fecha del sistema
        renglones.add(new RenglonEstatus("%03d".formatted(d.sistema()), msg, d.fechaProceso()));
    }
    return renglones;   // informativo: un sistema atrasado no detiene la proyección
}

@Override
@Transactional
public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
    ControlCorporativo cc = control.leeConBloqueo();            // SELECT ... FOR UPDATE
    LocalDate proxima = proyecta(cc.header());                   // segmento anterior
    reporte.emite(estatus(cc));                                  // V01-REPORTE

    int n = control.actualizaFechaHeader(cc.header().fechaProceso(), proxima);
    if (n != 1) {                                                // REWRITE ... INVALID KEY
        bitacora.error("ERROR AL ACTUALIZAR FECHA DE PROXIMO PROCESO");
        throw new ProcesoAbortadoException("REWRITE del header de control");
    }
    bitacora.info("FIN DE PROCESO PROYECCION DE FECHA Y STATUS");
    return RepeatStatus.FINISHED;
}

/** Pivote Y2K del copy de mensajes: AA < 50 es 20AA, de lo contrario 19AA. */
static final int PIVOTE_SIGLO = 50;

static int sigloDe(int aa) {
    return aa < PIVOTE_SIGLO ? 20 : 19;
}

